(function(){
  var style=document.createElement('style'); style.textContent='.salary-overview-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:20px 0 28px}.salary-overview-card{display:grid;gap:8px;padding:18px;border:1px solid #d4d0c7;border-radius:8px;background:#fffdf8}.salary-overview-card span,.salary-field-card small{color:#697077;font-size:.76rem}.salary-overview-card strong{font-size:1.2rem}.salary-overview-card p{margin:0;color:#697077;font-size:.82rem;line-height:1.5}.salary-overview-card-primary{border-color:#f25a28;background:#fff4ec}.salary-fields-section,.salary-sources-section{margin-top:28px}.salary-fields-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.salary-field-card{display:flex;gap:12px;align-items:flex-start;padding:14px;border:1px solid #d4d0c7;border-radius:8px;background:#fffdf8}.salary-field-card strong,.salary-field-card small{display:block}.salary-field-card p{margin:6px 0 0;color:#697077;font-size:.8rem}.status-dot-muted{background:#9aa3ad}.text-button{border:0;background:transparent;color:#f25a28;cursor:pointer;font:inherit;font-size:.82rem}.salary-audit-note{margin-top:12px;padding:14px 16px;border-left:2px solid #f25a28;background:#fff4ec;color:#697077;font-size:.84rem;line-height:1.65}.salary-audit-note strong{color:#1d2226}.salary-audit-note p{margin:6px 0 0}.salary-source-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.salary-source-list a{display:grid;grid-template-columns:1fr auto;gap:5px 10px;padding:14px;border:1px solid #d4d0c7;border-radius:8px;background:#fffdf8;color:inherit;text-decoration:none}.salary-source-list a:hover{border-color:#f25a28}.salary-source-list span{font-weight:700}.salary-source-list small{grid-column:1/-1;color:#697077;font-size:.76rem;line-height:1.45}@media(max-width:900px){.salary-overview-grid,.salary-source-list{grid-template-columns:1fr 1fr}}@media(max-width:620px){.salary-overview-grid,.salary-fields-grid,.salary-source-list{grid-template-columns:1fr}}'; document.head.appendChild(style);
  var paths=['/salary','/salaries','/salary/player','/salary/compare','/salary/team-compare'];
  function render(){
    if(paths.indexOf(location.pathname.replace(/\/$/,''))<0)return;
    var panel=document.querySelector('.unavailable-panel');
    if(!panel||panel.dataset.salaryEnhanced==='1')return;
    panel.dataset.salaryEnhanced='1'; panel.className='salary-legacy-panel';
    panel.innerHTML='<div class="salary-overview-grid" aria-label="薪资数据状态"><article class="salary-overview-card salary-overview-card-primary"><span>当前状态</span><strong>等待可信数据源</strong><p>不会用估算值或旧合同填充金额。</p></article><article class="salary-overview-card"><span>已核验公开脚本</span><strong>0 个薪资字段</strong><p>参考仓库当前公开脚本聚焦对位、打法、球队与球员日志。</p></article><article class="salary-overview-card"><span>接入门槛</span><strong>4 项校验</strong><p>来源、赛季、币种、更新时间均需进入 manifest。</p></article></div><section class="salary-fields-section"><div class="section-title"><div><span class="eyebrow">SCHEMA CHECK</span><h2>计划接入字段</h2></div><button class="text-button" type="button" data-salary-audit>查看核验说明 ↗</button></div><div class="salary-fields-grid"><article class="salary-field-card"><span class="status-dot status-dot-muted"></span><div><strong>球员薪资</strong><small>未发布</small><p>需要逐球员赛季薪资与币种字段</p></div></article><article class="salary-field-card"><span class="status-dot status-dot-muted"></span><div><strong>合同年限</strong><small>未发布</small><p>需要合同起止赛季和选项年字段</p></div></article><article class="salary-field-card"><span class="status-dot status-dot-muted"></span><div><strong>合同总额</strong><small>未发布</small><p>需要可追溯的合同来源与校验时间</p></div></article><article class="salary-field-card"><span class="status-dot status-dot-muted"></span><div><strong>球队工资总额</strong><small>未发布</small><p>需要球队赛季薪资汇总字段</p></div></article></div><div class="salary-audit-note" hidden><strong>核验结论</strong><p>参考站公开页面与 suren504/surennba_stats 当前没有可直接复用的 salary、contract 或 payroll 输出。接入前需要新增独立数据源，并通过字段完整性、赛季一致性和更新时间校验。</p></div></section><section class="salary-sources-section"><div class="section-title"><div><span class="eyebrow">SOURCE MAP</span><h2>可追溯数据入口</h2></div><span>点击查看原始来源</span></div><div class="salary-source-list"><a href="https://www.nba.com/stats" target="_blank" rel="noreferrer"><span>NBA Stats ↗</span><small>官方统计入口，不代表当前已提供薪资字段</small></a><a href="https://github.com/suren504/surennba_stats" target="_blank" rel="noreferrer"><span>参考 GitHub 仓库 ↗</span><small>查看公开抓取脚本与数据发布说明</small></a><a href="/courtmatch-analytics/methodology"><span>CourtMatch 数据口径 ↗</span><small>查看发布、质量门禁和字段说明</small></a></div></section>';
    var btn=panel.querySelector('[data-salary-audit]'),note=panel.querySelector('.salary-audit-note');
    if(btn)btn.addEventListener('click',function(){var hidden=note.hasAttribute('hidden'); if(hidden)note.removeAttribute('hidden'); else note.setAttribute('hidden',''); btn.textContent=hidden?'收起核验说明 ↗':'查看核验说明 ↗';});
  }
  new MutationObserver(render).observe(document.documentElement,{childList:true,subtree:true});
  [100,500,1200,2500].forEach(function(ms){setTimeout(render,ms)});
})();
